export function getEbookById(id: string): Ebook | undefined {
  return ebooks.find((book) => book.id === id)
}

/** Ebooks that have a cover image, for shelves and showcases. */
export function getFeaturedEbooks(limit = 24): Ebook[] {
  return ebooks.filter((book) => Boolean(book.cover)).slice(0, limit)
}

/**
 * Mixed shelf for home — round-robin from Classics, Yoga, and Cooking
 * so the wall shows a blend of the library.
 */
export function getMixedShelfEbooks(limit = 24): Ebook[] {
  const pools = ['Ebook', 'Yoga', 'Cooking'].map((category) =>
    ebooks.filter((book) => book.category === category && Boolean(book.cover)),
  )

  const mixed: Ebook[] = []
  const seen = new Set<string>()
  let index = 0

  while (mixed.length < limit) {
    let added = false
    for (const pool of pools) {
      const book = pool[index]
      if (book && !seen.has(book.id)) {
        seen.add(book.id)
        mixed.push(book)
        added = true
        if (mixed.length >= limit) break
      }
    }
    if (!added) break
    index += 1
  }

  return mixed
}

/**
 * Map CDN / API file URL → same-origin proxy path (avoids CORS).
 * Parses host manually so filenames with `&` / `;` are not treated as query strings.
 */
export function ebookProxyPath(fileUrl: string): string {
  try {
    const match = fileUrl.match(/^(https?):\/\/([^/]+)(\/.*)?$/i)
    if (!match) return fileUrl
    const host = match[2]!
    const pathAndQuery = match[3] || '/'
    // Keep already-encoded sequences; encode unsafe path chars for the proxy hop.
    const safePath = pathAndQuery
      .split('/')
      .map((segment, i) => {
        if (i === 0 && segment === '') return ''
        try {
          return encodeURIComponent(decodeURIComponent(segment))
        } catch {
          return encodeURIComponent(segment)
        }
      })
      .join('/')

    if (host === 'api.ameora.fun') {
      return `/yoga-ebook-proxy${safePath}`
    }
    return `/ebook-proxy${safePath}`
  } catch {
    return fileUrl
  }
}

/** Unique categories present in the catalog (sorted, Classics-style first). */
export function getEbookCategories(): string[] {
  const set = new Set(ebooks.map((book) => book.category))
  const order = ['Ebook', 'Yoga', 'Cooking']
  return [...set].sort((a, b) => {
    const ai = order.indexOf(a)
    const bi = order.indexOf(b)
    if (ai !== -1 || bi !== -1) {
      return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi)
    }
    return a.localeCompare(b)
  })
}

export function getEbooksByCategory(category: string): Ebook[] {
  return ebooks.filter(
    (book) => book.category.toLowerCase() === category.toLowerCase(),
  )
}

export function detectEbookFormat(fileUrl: string): EbookFormat {
  const pathOnly = fileUrl.split('?')[0]?.toLowerCase() ?? ''
  return pathOnly.endsWith('.pdf') ? 'pdf' : 'epub'
}
